// WAHA message event -> satu identitas kontak yang stabil; abaikan echo/duplikat event.
const b = $json.body ?? $json;
const p = b.payload ?? b;
const k = p.key ?? {};
const id = k.id ?? p.id ?? p.message?.id ?? p._data?.id ?? '';
const messageId = typeof id === 'string' ? id : (id?._serialized ?? id?.id ?? '');
const chat = p.from ?? p.chatId ?? k.remoteJid ?? p._data?.from ?? '';
const chatId = typeof chat === 'string' ? chat : '';
const rawFromMe = k.fromMe ?? p.fromMe ?? p._data?.id?.fromMe ?? false;
const fromMe = rawFromMe === true || rawFromMe === 'true';
const eventType = String(b.event ?? '');
const session = String(b.session ?? p.session ?? 'default');
const configuredSession = String($env.WAHA_SESSION || 'default');
const isGroup = chatId.endsWith('@g.us');
const inputText = p.body ?? p.text ?? p.message?.conversation ?? p._data?.body ?? '';
const hasMedia = Boolean(p.hasMedia || p.media?.mimetype || p.message?.imageMessage || p.message?.documentMessage || p.message?.audioMessage);
const messageText = typeof inputText === 'string' && inputText.trim() ? inputText.trim() : (hasMedia ? '[Lampiran diterima; pemeriksaan admin diperlukan]' : '');
const supportedChat = /^[0-9]+@(c\.us|s\.whatsapp\.net|lid)$/.test(chatId);
const valid = Boolean(messageId && supportedChat && eventType === 'message' && session === configuredSession && !fromMe && !isGroup && messageText);
return [{json:{
  valid, external_message_id:String(messageId), event_type:eventType,
  chat_id:chatId, phone:chatId.replace(/@.+$/,''),
  message_text:messageText, from_me:fromMe, is_group:isGroup,
  session, has_media:hasMedia, raw:b
}}];
